package net.minecraft.world.level.block.state;import net.minecraft.world.level.BlockGetter;import net.minecraft.core.BlockPos;import net.minecraft.world.phys.shapes.VoxelShape;import net.minecraft.world.level.material.FluidState;public class BlockState{public boolean air;public float hardness=1.5f;public boolean container;public BlockState(boolean air){this.air=air;}public VoxelShape getCollisionShape(BlockGetter l,BlockPos p){return new VoxelShape(air);}public float getDestroySpeed(BlockGetter l,BlockPos p){return hardness;}public boolean hasBlockEntity(){return container;}public FluidState getFluidState(){return new FluidState();}}
